		.map(
			(p) => `<item><title>${p.title}</title><link>${base}/blog/${p.slug}</link><description>${p.description}</description><pubDate>${new Date(p.published).toUTCString()}</pubDate><guid>${base}/blog/${p.slug}</guid></item>`
		)
		.join('\n');
	const body = `<?xml version="1.0" encoding="UTF-8"?>\n<rss version="2.0"><channel><title>x2 blog</title><link>${base}/blog</link><description>guides on meeting people online</description>\n${items}\n</channel></rss>`;
	return new Response(body, { headers: { 'content-type': 'application/rss+xml; charset=utf-8' } });
};
